mapper.select:
SELECT receiver_area_id AS areaId, (SELECT COUNT(DISTINCT s.user_id) FROM trade_order AS s WHERE s.receiver_area_id = m.receiver_area_id
AND s.tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
) AS orderCreateUserCount, (SELECT COUNT(DISTINCT s.user_id) FROM trade_order AS s WHERE s.receiver_area_id = m.receiver_area_id AND s.pay_status = TRUE AND s.deleted = FALSE
AND s.tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
) AS orderPayUserCount, (SELECT SUM(s.pay_price) FROM trade_order AS s WHERE s.receiver_area_id = m.receiver_area_id AND s.pay_status = TRUE AND s.deleted = FALSE
AND s.tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
) AS orderPayPrice FROM trade_order m WHERE deleted = FALSE
AND m.tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
GROUP BY receiver_area_id

SELECT COUNT(DISTINCT (user_id))
FROM trade_order
WHERE deleted = FALSE
  AND create_time BETWEEN #{beginTime} AND #{endTime}

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT COUNT(DISTINCT (user_id))
FROM trade_order
WHERE pay_time BETWEEN #{beginTime} AND #{endTime}
  AND pay_status = TRUE
  AND deleted = FALSE

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT COUNT(1)
FROM trade_order
WHERE create_time BETWEEN #{beginTime} AND #{endTime}
  AND deleted = FALSE

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT COUNT(1)
FROM trade_order
WHERE pay_status = TRUE
  AND create_time BETWEEN #{beginTime} AND #{endTime}
  AND deleted = FALSE

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT SUM(pay_price)
FROM trade_order AS s
WHERE s.pay_status = TRUE
  AND deleted = FALSE
  AND create_time BETWEEN #{beginTime} AND #{endTime}

    AND s.tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT DATE_FORMAT(pay_time, '%Y-%m-%d') AS date, COUNT(1) AS orderPayCount, SUM(pay_price) AS orderPayPrice FROM trade_order WHERE pay_status = TRUE AND create_time BETWEEN #{beginTime} AND #{endTime} AND deleted = FALSE
AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
GROUP BY date

SELECT DATE_FORMAT(pay_time, '%Y-%m') AS date, COUNT(1) AS order_pay_count, SUM(pay_price) AS order_pay_price FROM trade_order WHERE pay_status = TRUE AND create_time BETWEEN #{beginTime} AND #{endTime} AND deleted = FALSE
AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
GROUP BY date

SELECT COUNT(1)
FROM trade_order
WHERE status = #{status}
  ANd delivery_type = #{deliveryType}
  AND deleted = FALSE

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT IFNULL(SUM(pay_price), 0) AS order_pay_price,
       COUNT(1)                  AS order_pay_count
FROM trade_order
WHERE pay_status = #{payStatus}
  AND pay_time BETWEEN #{beginTime} AND #{endTime}
  AND deleted = FALSE

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
